{"command":"cd /workspace && cat > src/natsort.rs <<'EOF'
//! Natural ("human") ordering of strings.
//!
//! Digit runs are compared numerically, whitespace is skipped and runs of
//! digits that start with a zero are compared as if they were fractional
//! parts (left aligned, digit by digit).

use std::cmp::Ordering;

fn is_digit(c: Option<&char>) -> bool {
    matches!(c, Some(c) if c.is_ascii_digit())
}

/// Compares two digit runs that are left aligned (one of them starts with a
/// zero). The first differing digit decides; a shorter run is smaller.
fn compare_left(a: &[char], b: &[char]) -> Ordering {
    let mut i = 0;
    loop {
        let (ca, cb) = (a.get(i), b.get(i));
        match (is_digit(ca), is_digit(cb)) {
            (false, false) => return Ordering::Equal,
            (false, true) => return Ordering::Less,
            (true, false) => return Ordering::Greater,
            (true, true) => {
                let (x, y) = (ca.unwrap(), cb.unwrap());
                if x < y {
                    return Ordering::Less;
                }
                if x > y {
                    return Ordering::Greater;
                }
            }
        }
        i += 1;
    }
}

/// Compares two digit runs that are right aligned: the longest run wins,
/// otherwise the first differing digit decides.
fn compare_right(a: &[char], b: &[char]) -> Ordering {
    let mut bias = Ordering::Equal;
    let mut i = 0;
    loop {
        let (ca, cb) = (a.get(i), b.get(i));
        match (is_digit(ca), is_digit(cb)) {
            (false, false) => return bias,
            (false, true) => return Ordering::Less,
            (true, false) => return Ordering::Greater,
            (true, true) => {
                let (x, y) = (ca.unwrap(), cb.unwrap());
                if bias == Ordering::Equal {
                    bias = x.cmp(y);
                }
            }
        }
        i += 1;
    }
}

/// Natural comparison of two strings.
pub fn compare(left: &str, right: &str) -> Ordering {
    let a: Vec<char> = left.chars().collect();
    let b: Vec<char> = right.chars().collect();
    let (mut ai, mut bi) = (0usize, 0usize);

    loop {
        while ai < a.len() && a[ai].is_whitespace() {
            ai += 1;
        }
        while bi < b.len() && b[bi].is_whitespace() {
            bi += 1;
        }

        let (ca, cb) = (a.get(ai), b.get(bi));

        if is_digit(ca) && is_digit(cb) {
            let fractional = *ca.unwrap() == '0' || *cb.unwrap() == '0';
            let result = if fractional {
                compare_left(&a[ai..], &b[bi..])
            } else {
                compare_right(&a[ai..], &b[bi..])
            };
            if result != Ordering::Equal {
                return result;
            }
        }

        match (ca, cb) {
            (None, None) => return Ordering::Equal,
            (None, Some(_)) => return Ordering::Less,
            (Some(_), None) => return Ordering::Greater,
            (Some(x), Some(y)) => match x.cmp(y) {
                Ordering::Equal => {}
                other => return other,
            },
        }

        ai += 1;
        bi += 1;
    }
}

#[cfg(test)]
mod tests {
    use super::compare;
    use std::cmp::Ordering::*;

    #[test]
    fn basics() {
        assert_eq!(compare("file 2.jpg", "file 10.jpg"), Less);
        assert_eq!(compare("a", "B"), Greater);
        assert_eq!(compare("a1", "a 1"), Equal);
        assert_eq!(compare("a ", "a"), Equal);
        assert_eq!(compare("001", "01"), Less);
        assert_eq!(compare("01", "1"), Less);
        assert_eq!(compare("1.50", "1.5"), Greater);
        assert_eq!(compare("1.05", "1.5"), Less);
        assert_eq!(compare("10", "1 0"), Greater);
        assert_eq!(compare("a01b2", "a1"), Less);
        assert_eq!(compare("0a", "00b"), Less);
        assert_eq!(compare("x 1", "x-1"), Greater);
    }
}
EOF
echo done"}

