#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FormatError(String);

impl fmt::Display for FormatError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "[output-format] {}", self.0)
    }
}

impl std::error::Error for FormatError {}

/// Source of values for placeholders.
pub trait Captures {
    fn by_index(&self, index: usize) -> Option<&str>;
    fn by_name(&self, name: &str) -> Option<&str>;
}

#[derive(Debug, Clone)]
pub struct OutputFormat {
    segments: Vec<Segment>,
}

impl OutputFormat {
    pub fn parse(pattern: &str) -> Result<Self, FormatError> {
        let chars: Vec<char> = pattern.chars().collect();
        let mut segments = Vec::new();
        let mut buffer = String::new();
        let mut in_placeholder = false;
        let mut next_auto_index = 1usize;
        let mut i = 0usize;

        while i < chars.len() {
            let c = chars[i];
            match c {
                '\\' => {
                    i += 1;
                    if let Some(&escaped) = chars.get(i) {
                        match escaped {
                            '{' | '}' | '\\' => buffer.push(escaped),
                            other => {
                                return Err(FormatError(format!(
                                    "invalid escape character of '{}' at '{}'",
                                    other, i
                                )))
                            }
                        }
                    }
                }
                '{' if !in_placeholder => {
                    if !buffer.is_empty() {
                        segments.push(Segment::Text(std::mem::take(&mut buffer)));
                    }
                    in_placeholder = true;
                }
                '}' => {
                    if !in_placeholder {
                        return Err(FormatError(
                            "an unopened placeholder could not be closed by '}'".to_string(),
                        ));
                    }
                    let content = std::mem::take(&mut buffer);
                    segments.push(parse_placeholder(&content, &mut next_auto_index)?);
                    in_placeholder = false;
                }
                _ => buffer.push(c),
            }
            i += 1;
        }

        if in_placeholder {
            return Err(FormatError(
                "all opened placeholders must be closed by '}'".to_string(),
            ));
        }
        if !buffer.is_empty() {
            segments.push(Segment::Text(buffer));
        }

        Ok(OutputFormat { segments })
    }

