    pub fn render<C: Captures>(&self, captures: &C) -> String {
        let mut out = String::new();
        for segment in &self.segments {
            match segment {
                Segment::Text(text) => out.push_str(text),
                Segment::Placeholder { group, padding } => {
                    let value = match group {
                        Group::Index(index) => captures.by_index(*index),
                        Group::Name(name) => captures.by_name(name),
                    }
                    .unwrap_or("");
                    match padding {
                        Some(width) => match value.parse::<u64>() {
                            Ok(number) => out.push_str(&format!("{:0>width$}", number, width = *width)),
                            Err(_) => out.push_str(value),
                        },
                        None => out.push_str(value),
                    }
                }
            }
        }
        out
    }
}

fn parse_placeholder(content: &str, next_auto_index: &mut usize) -> Result<Segment, FormatError> {
    let (group_part, padding_part) = match content.find(':') {
        Some(pos) => (&content[..pos], Some(&content[pos + 1..])),
        None => (content, None),
    };

    let group = if group_part.is_empty() {
        let index = *next_auto_index;
        *next_auto_index += 1;
        Group::Index(index)
    } else if let Ok(index) = group_part.parse::<usize>() {
        Group::Index(index)
    } else {
        Group::Name(group_part.to_string())
    };

    let padding = match padding_part {
        None | Some("") => None,
        Some(text) => match text.parse::<usize>() {
            Ok(width) => Some(width),
            Err(_) => {
                return Err(FormatError(format!("unable to parse padding of '{}'", text)));
            }
        },
    };

    Ok(Segment::Placeholder { group, padding })
}

