        assert_eq!(f.render(&Vals(vec!["a", "-1"])), "-1");
    }

    #[test]
    fn errors() {
        assert!(OutputFormat::parse("x{").is_err());
        assert!(OutputFormat::parse("x}").is_err());
        assert!(OutputFormat::parse("{1:a}").is_err());
        assert!(OutputFormat::parse("a\\n").is_err());
        assert_eq!(OutputFormat::parse("q\\").unwrap().render(&Vals(vec![])), "q");
    }
}
