//! Minimal ASCII table rendering used to print the rename map.

use std::io::{self, Write};
use unicode_width::UnicodeWidthStr;

/// A table with a header row and any number of body rows. Cells may contain
/// multiple lines separated by `\n`.
pub struct Table {
    header: Vec<String>,
    rows: Vec<Vec<String>>,
}

impl Table {
    pub fn new(header: Vec<String>) -> Self {
        Table {
            header,
            rows: Vec::new(),
        }
    }

    pub fn add_row(&mut self, row: Vec<String>) {
        self.rows.push(row);
    }

    fn column_count(&self) -> usize {
        self.rows
            .iter()
            .map(|r| r.len())
            .chain(std::iter::once(self.header.len()))
            .max()
            .unwrap_or(0)
    }

    fn column_widths(&self) -> Vec<usize> {
        let count = self.column_count();
        let mut widths = vec![0usize; count];
        for row in std::iter::once(&self.header).chain(self.rows.iter()) {
            for (i, cell) in row.iter().enumerate() {
                let w = cell.split('\n').map(UnicodeWidthStr::width).max().unwrap_or(0);
                if w > widths[i] {
                    widths[i] = w;
                }
            }
        }
        widths
    }

    fn write_separator<W: Write>(&self, out: &mut W, widths: &[usize]) -> io::Result<()> {
        out.write_all(b"+")?;
        for w in widths {
            out.write_all("-".repeat(w + 2).as_bytes())?;
            out.write_all(b"+")?;
        }
        out.write_all(b"\n")
    }

    fn write_row<W: Write>(&self, out: &mut W, widths: &[usize], row: &[String]) -> io::Result<()> {
        let cells: Vec<Vec<&str>> = (0..widths.len())
            .map(|i| row.get(i).map(|c| c.split('\n').collect()).unwrap_or_default())
            .collect();
        let height = cells.iter().map(|c| c.len()).max().unwrap_or(1).max(1);
        for line in 0..height {
            out.write_all(b"|")?;
            for (i, width) in widths.iter().enumerate() {
                let text = cells[i].get(line).copied().unwrap_or("");
                let pad = width.saturating_sub(UnicodeWidthStr::width(text));
                out.write_all(b" ")?;
                out.write_all(text.as_bytes())?;
                out.write_all(" ".repeat(pad).as_bytes())?;
                out.write_all(b" |")?;
            }
            out.write_all(b"\n")?;
        }
        Ok(())
    }

    pub fn print<W: Write>(&self, out: &mut W) -> io::Result<()> {
        let widths = self.column_widths();
        self.write_separator(out, &widths)?;
        self.write_row(out, &widths, &self.header)?;
        self.write_separator(out, &widths)?;
        for row in &self.rows {
            self.write_row(out, &widths, row)?;
        }
        self.write_separator(out, &widths)
    }
}
