//! nomino - batch rename utility for developers.

mod cli;
mod format;
mod natsort;
mod table;

use cli::SortOrder;
use format::{Captures, OutputFormat};
use regex::Regex;
use std::collections::{BTreeMap, HashMap};
use std::ffi::OsStr;
use std::fs;
use std::io::{self, IsTerminal, Write};
use std::path::{Path, PathBuf};
use table::Table;
use walkdir::WalkDir;

/// Handles optional ANSI styling of messages written to stderr.
struct Style {
    enabled: bool,
}

impl Style {
    fn new() -> Self {
        Style {
            enabled: io::stderr().is_terminal(),
        }
    }

    fn paint(&self, text: &str, code: &str) -> String {
        if self.enabled {
            format!("\x1b[{}m{}\x1b[0m", code, text)
        } else {
            text.to_string()
        }
    }

    fn error(&self) -> String {
        self.paint("error", "1;31")
    }

    fn usage(&self) -> String {
        self.paint("usage", "1;33")
    }

    fn cyan(&self, text: &str) -> String {
        self.paint(text, "36")
    }
}

/// Options that affect how a single rename is performed.
struct RenameOptions {
    test: bool,
    overwrite: bool,
    mkdir: bool,
}

/// Collects results of the renaming process: a map of output -> input.
struct Renamer<'a> {
    options: RenameOptions,
    style: &'a Style,
    map: BTreeMap<String, String>,
    failed: bool,
}

impl<'a> Renamer<'a> {
    fn new(options: RenameOptions, style: &'a Style) -> Self {
        Renamer {
            options,
            style,
            map: BTreeMap::new(),
            failed: false,
        }
    }

    /// Prepends `_` to the file name of a path.
    fn prefix_underscore(path: &str) -> String {
        let p = Path::new(path);
        let name = p
            .file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_default();
        p.with_file_name(format!("_{}", name))
            .to_string_lossy()
            .into_owned()
    }

    fn process(&mut self, input: String, mut output: String) {
        if !self.options.overwrite {
            while output != input && Path::new(&output).exists() {
                output = Self::prefix_underscore(&output);
            }
        }

        if self.options.mkdir {
            if let Some(parent) = Path::new(&output).parent() {
                if !parent.as_os_str().is_empty() {
                    // Failures are reported by the rename itself.
                    let _ = fs::create_dir_all(parent);
                }
            }
        }

        if !self.options.test {
            if let Err(err) = fs::rename(&input, &output) {
                eprintln!(
                    "[{}] unable to rename '{}': {}",
                    self.style.error(),
                    input,
                    err
                );
                self.failed = true;
                return;
            }
        }

        self.map.insert(output, input);
    }
}

/// Captures backed by a regex match.
struct RegexCaptures<'t>(regex::Captures<'t>);

impl<'t> Captures for RegexCaptures<'t> {
    fn by_index(&self, index: usize) -> Option<&str> {
        self.0.get(index).map(|m| m.as_str())
    }

    fn by_name(&self, name: &str) -> Option<&str> {
        self.0.name(name).map(|m| m.as_str())
    }
}

/// Captures used in sort mode: `{0}` is the file name, `{1}` the enumerator.
struct SortCaptures {
    values: [String; 2],
}

impl Captures for SortCaptures {
    fn by_index(&self, index: usize) -> Option<&str> {
        self.values.get(index).map(|s| s.as_str())
    }

    fn by_name(&self, _name: &str) -> Option<&str> {
        None
    }
}

/// Appends the extension of `input` to `output` when extensions are preserved.
fn with_extension(input: &str, output: String, keep_extension: bool) -> String {
    if !keep_extension {
        return output;
    }
    match Path::new(input).extension() {
        Some(ext) => format!("{}.{}", output, ext.to_string_lossy()),
        None => output,
    }
}

fn path_to_string(path: &Path) -> String {
    path.to_string_lossy().into_owned()
}

fn print_error(style: &Style, message: &str) {
    eprintln!("{}: {}", style.error(), message);
}

fn run() -> i32 {
    let matches = cli::build_command().get_matches();
    let style = Style::new();

    if let Some(dir) = matches.get_one::<PathBuf>(cli::ARG_DIR) {
        if let Err(err) = std::env::set_current_dir(dir) {
            print_error(&style, &err.to_string());
            return 1;
        }
    }

    let positionals: Vec<String> = matches
        .get_many::<String>(cli::ARG_OUTPUT)
        .map(|values| values.cloned().collect())
        .unwrap_or_default();
    let regex_flag = matches.get_one::<String>(cli::ARG_REGEX).cloned();
    let sort_flag = matches
        .get_one::<String>(cli::ARG_SORT)
        .and_then(|s| SortOrder::from_name(s));
    let map_flag = matches.get_one::<PathBuf>(cli::ARG_MAP).cloned();

    let (source, output) = match positionals.len() {
        0 => (None, None),
        1 => (None, Some(positionals[0].clone())),
        n => (
            Some(positionals[n - 2].clone()),
            Some(positionals[n - 1].clone()),
        ),
    };

    if source.is_some() && (regex_flag.is_some() || sort_flag.is_some() || map_flag.is_some()) {
        print_error(
            &style,
            "optional SOURCE must be used without setting regex, map or sort flags",
        );
        return 1;
    }

    let pattern = regex_flag.or(source);

    if pattern.is_none() && sort_flag.is_none() && map_flag.is_none() {
        eprintln!(
