    ARG_QUIET,
    ARG_MAP,
    ARG_SORT,
    ARG_REGEX,
    ARG_OUTPUT,
];

const AFTER_HELP: &str = "OUTPUT pattern accepts placeholders that have the format of '{G:P}' where 'G' is \
the captured group and 'P' is the padding of digits with `0`. Please refer to \
https://github.com/yaa110/nomino for more information.";

/// Sorting order used by the `--sort` option.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SortOrder {
    Asc,
    Desc,
}

impl SortOrder {
    /// Resolves the (case-insensitive) order name.
    pub fn from_name(name: &str) -> Option<Self> {
        if name.eq_ignore_ascii_case("asc") {
            Some(SortOrder::Asc)
        } else if name.eq_ignore_ascii_case("desc") {
            Some(SortOrder::Desc)
        } else {
            None
        }
    }
}

fn path_arg(id: &'static str) -> Arg {
    Arg::new(id)
        .value_name("PATH")
        .value_parser(value_parser!(PathBuf))
        .action(ArgAction::Set)
}

fn depth_arg(id: &'static str) -> Arg {
    Arg::new(id)
        .value_name("DEPTH")
        .value_parser(value_parser!(usize))
        .action(ArgAction::Set)
}

fn flag_arg(id: &'static str) -> Arg {
    Arg::new(id).action(ArgAction::SetTrue)
}

fn make_arg(id: &'static str) -> Arg {
    match id {
        ARG_TEST => flag_arg(id)
            .short('t')
            .long("test")
            .visible_alias("dry-run")
            .help("Runs in test mode without renaming actual files"),
        ARG_MKDIR => flag_arg(id)
            .short('k')
            .long("mkdir")
            .help("Recursively creates all parent directories of '<OUTPUT>' if they are missing"),
        ARG_OVERWRITE => flag_arg(id)
            .short('w')
            .long("overwrite")
            .help("Overwrites output files, otherwise, a '_' is prepended to filename"),
        ARG_NO_EXTENSION => flag_arg(id)
            .short('E')
            .long("no-extension")
            .help("Does not preserve the extension of input files in 'sort' and 'regex' options"),
        ARG_DIR => path_arg(id)
            .short('d')
            .long("dir")
            .help("Sets the working directory"),
        ARG_MAX_DEPTH => depth_arg(id)
            .long("max-depth")
            .help("Optional value to set the maximum of subdirectory depth value in 'regex' mode"),
        ARG_DEPTH => depth_arg(id)
            .long("depth")
            .help("Optional value to overwrite inferred subdirectory depth value in 'regex' mode"),
        ARG_GENERATE => path_arg(id)
            .short('g')
            .long("generate")
            .help("Stores a JSON map file in '<PATH>' after renaming files"),
        ARG_QUIET => flag_arg(id)
            .short('q')
            .long("quiet")
            .help("Does not print the map table to stdout"),
        ARG_MAP => path_arg(id)
            .short('m')
            .long("map")
            .visible_alias("from-file")
            .help("Sets the path of map file to be used for renaming files"),
        ARG_SORT => Arg::new(id)
            .short('s')
            .long("sort")
            .value_name("ORDER")
            .action(ArgAction::Set)
            .ignore_case(true)
            .value_parser([
                PossibleValue::new("asc").help("Sort in ascending order"),
                PossibleValue::new("desc").help("Sort in descending order"),
            ])
            .help("Sets the order of natural sorting (by name) to rename files using enumerator"),
        ARG_REGEX => Arg::new(id)
            .short('r')
            .long("regex")
            .value_name("PATTERN")
            .action(ArgAction::Set)
            .requires(ARG_OUTPUT)
            .help("Regex pattern to match by filenames"),
        ARG_OUTPUT => Arg::new(id)
            .value_name("[SOURCE] OUTPUT")
            .num_args(1..)
            .action(ArgAction::Append)
            .help(
                "OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional \
                 regex pattern to match by filenames. SOURCE has the same function as -r option",
            ),
        other => unreachable!("unknown argument id {other}"),
    }
}

/// Builds the clap command describing the CLI.
pub fn build_command() -> Command {
    let mut command = Command::new("nomino")
        .version("1.6.4")
        .about("Batch rename utility for developers")
        .after_help(AFTER_HELP)
        // All arguments share the same display order so that the help output
        // is sorted alphabetically by flag.
        .next_display_order(None);

    for id in ARG_ORDER {
        command = command.arg(make_arg(id));
    }

    command.group(ArgGroup::new(GROUP_ALL).multiple(true).args(ARG_ORDER))
}
